/* ---------- Waktu (WIB) ---------- */
const TZ = 'Asia/Jakarta';
const fmt = (ms, o) => { try { return new Date(Number(ms)).toLocaleString('id-ID', Object.assign({ timeZone: TZ }, o)); } catch (e) { return ''; } };
