function sisa(ms) { const t = Number(ms) - Date.now(), a = Math.abs(t), d = Math.floor(a / 864e5), h = Math.floor(a % 864e5 / 36e5), m = Math.floor(a % 36e5 / 6e4), s = Math.floor(a % 6e4 / 1e3); return { t, d, h, m, s, late: t < 0 }; }
function sisaTeks(ms) { const x = sisa(ms); const p = x.d ? x.d + ' hari ' + x.h + ' jam' : x.h ? x.h + ' jam ' + x.m + ' mnt' : x.m + ' mnt'; return x.late ? 'lewat ' + p : p + ' lagi'; }
