/* ---------- Komponen UI ---------- */
const TONE = { Hadir: 'ok', Terlambat: 'warn', Izin: 'info', Sakit: 'warn', Alpa: 'err', Dinilai: 'ok', Dikumpulkan: 'info', Belum: 'err', Revisi: 'warn', Aktif: 'ok', Nonaktif: 'neu', Terkunci: 'err', Terbit: 'ok', Draft: 'neu', Ditutup: 'neu', Selesai: 'neu', Penting: 'err', Biasa: 'neu', Lulus: 'ok', Remedial: 'err' };
