const GR_TONE = g => /^A/.test(g) ? 'ok' : /^B/.test(g) ? 'info' : /^C/.test(g) ? 'warn' : 'err';
const gradeChip = g => g ? `<span class="chip c-${GR_TONE(g)}">${E(g)}</span>` : '<span class="mut">–</span>';
const kpi = o => `<div class="card kpi"><span class="ic ${o.tone || ''}">${icon(o.icon || 'bar-chart')}</span><span class="l">${E(o.l)}</span><span class="v">${o.v}${o.u ? `<small>${o.u}</small>` : ''}</span>${o.bar != null ? `<div class="bar sm ${o.bt || ''}"><i style="width:${Math.max(0, Math.min(100, o.bar))}%"></i></div>` : ''}${o.s ? `<span class="sm mut">${o.s}</span>` : ''}</div>`;
const empty = (ic, msg, cta) => `<div class="empty">${icon(ic || 'inbox')}<div>${E(msg)}</div>${cta || ''}</div>`;
