const phead = o => `<div class="ph"><div><div class="tags">${o.tag ? `<span class="chip c-neu mono">${E(o.tag)}</span>` : ''}${o.sync ? `<span class="chip c-ok"><i class="dt pulse"></i>${E(o.sync)}</span>` : ''}</div><h1>${E(o.t)}</h1>${o.s ? `<p class="sub">${E(o.s)}</p>` : ''}</div><div class="acts">${o.a || ''}</div></div>`;
const cardH = (t, s, a) => `<div class="ch"><div><h3>${t}</h3>${s ? `<p>${s}</p>` : ''}</div><div class="row wrap">${a || ''}</div></div>`;
const prog = (v, tone) => `<div class="bar ${tone || ''}"><i style="width:${Math.max(0, Math.min(100, v || 0))}%"></i></div>`;
const btn = (label, act, o) => { o = o || {}; return `<button class="btn ${o.c || 'btn-s'} ${o.sm ? 'btn-sm' : ''}" data-act="${act}" ${Object.keys(o.d || {}).map(k => `data-${k}="${E(o.d[k])}"`).join(' ')} ${o.dis ? 'disabled' : ''} ${o.t ? `title="${E(o.t)}"` : ''}>${o.i ? icon(o.i) : ''}${label ? `<span>${label}</span>` : ''}</button>`; };
const fld = (label, inner, hint) => `<div class="fld"><label>${E(label)}</label>${inner}${hint ? `<span class="hint">${hint}</span>` : ''}</div>`;
const opts = (arr, sel) => arr.map(o => { const v = Array.isArray(o) ? o[0] : o, l = Array.isArray(o) ? o[1] : o; return `<option value="${E(v)}" ${String(v) === String(sel) ? 'selected' : ''}>${E(l)}</option>`; }).join('');
const fval = (k, d) => S.f[k] === undefined ? d : S.f[k];
const qval = k => S.q[k] || '';
const selx = (k, arr, d, cls) => `<select class="sel ${cls || ''}" data-change="f" data-key="${k}" aria-label="${E(k)}">${opts(arr, fval(k, d))}</select>`;
const qinp = (k, ph) => `<div class="srch" style="max-width:none"><i class="bi bi-search"></i><input class="inp" data-input="q" data-key="q_${k}" value="${E(qval(k))}" placeholder="${E(ph)}" aria-label="${E(ph)}" autocomplete="off"></div>`;
const tabs = (k, items, d, ul) => { const cur = fval(k, d); return `<div class="tabs ${ul ? 'ul' : ''}" role="tablist">${items.map(i => `<button role="tab" class="${String(i[0]) === String(cur) ? 'on' : ''}" data-act="tab" data-key="${k}" data-v="${E(i[0])}">${E(i[1])}${i[2] != null ? `<span class="n">${i[2]}</span>` : ''}</button>`).join('')}</div>`; };
function paged(k, arr, per) { per = per || 8; const pages = Math.max(1, Math.ceil(arr.length / per)); let p = Math.min(S.pg[k] || 1, pages); S.pg[k] = p; const items = arr.slice((p - 1) * per, p * per); const nums = []; for (let i = 1; i <= pages; i++) if (i === 1 || i === pages || Math.abs(i - p) <= 1) nums.push(i); else if (nums[nums.length - 1] !== '…') nums.push('…'); const html = arr.length > per ? `<div class="pager"><span>Menampilkan <b>${(p - 1) * per + 1}–${Math.min(p * per, arr.length)}</b> dari <b>${arr.length}</b></span><div class="pg"><button data-act="pg" data-key="${k}" data-p="${p - 1}" ${p <= 1 ? 'disabled' : ''} aria-label="Sebelumnya">${icon('chevron-left')}</button>${nums.map(n => n === '…' ? '<button disabled>…</button>' : `<button class="${n === p ? 'on' : ''}" data-act="pg" data-key="${k}" data-p="${n}">${n}</button>`).join('')}<button data-act="pg" data-key="${k}" data-p="${p + 1}" ${p >= pages ? 'disabled' : ''} aria-label="Berikutnya">${icon('chevron-right')}</button></div></div>` : `<div class="pager"><span>${arr.length} data</span></div>`; return { items, html }; }
function tbl(cols, rows, o) { o = o || {}; return `<div class="tbl-wrap"><table class="tbl ${o.cls || ''}"><thead><tr>${cols.map(c => `<th class="${c.cls || ''}">${c.raw ? c.h : E(c.h)}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.map(r => `<tr class="${o.rc ? o.rc(r) : ''}">${cols.map(c => `<td class="${c.cls || ''}">${c.r(r)}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${cols.length}">${empty(o.ei || 'inbox', o.em || 'Belum ada data.')}</td></tr>`}</tbody></table></div>`; }
const skeleton = () => `<div class="g g4">${'<div class="sk" style="height:110px"></div>'.repeat(4)}</div><div class="sk mt" style="height:220px"></div><div class="g g2 mt"><div class="sk" style="height:260px"></div><div class="sk" style="height:260px"></div></div>`;

/* ---------- Toast & Modal ---------- */
function toast(msg, tone) { const el = document.createElement('div'); el.className = 'toast ' + (tone || 'info'); el.setAttribute('role', tone === 'danger' ? 'alert' : 'status'); el.innerHTML = `${icon(tone === 'success' ? 'check-circle-fill' : tone === 'danger' ? 'x-octagon-fill' : tone === 'warn' ? 'exclamation-triangle-fill' : 'info-circle-fill')}<div class="f1 sm" style="font-size:13px">${E(msg)}</div>`; $('#toasts').appendChild(el); setTimeout(() => el.remove(), tone === 'danger' ? 6000 : 3500); }
function modal(o) { const root = $('#modal-root'); root.innerHTML = `<div class="ov" data-act="modal.bg"><div class="mdl ${o.cls || ''}" role="dialog" aria-modal="true" aria-label="${E(o.title)}"><header><h3>${E(o.title)}</h3><button class="ib sm" data-act="modal.close" aria-label="Tutup">${icon('x-lg')}</button></header><div class="bd" id="mdl-body">${o.body}</div>${o.foot ? `<footer id="mdl-foot">${o.foot}</footer>` : ''}</div></div>`; const f = $('input,select,textarea,button.btn-p', root.querySelector('.bd')); if (f && !o.noFocus) setTimeout(() => f.focus(), 30); o.open && o.open(root); }
function closeModal() { $('#modal-root').innerHTML = ''; if (S.dirty) { S.dirty = false; render(); } }
function confirmBox(msg, onOk, label, danger) { S.onOk = onOk; modal({ title: 'Konfirmasi', body: `<p>${msg}</p>`, foot: `${btn('Batal', 'modal.close')}${btn(label || 'Ya, lanjutkan', 'confirm.ok', { c: danger ? 'btn-d' : 'btn-p' })}`, noFocus: true }); }
ACT['modal.close'] = closeModal; ACT['modal.bg'] = closeModal;
ACT['confirm.ok'] = () => { const f = S.onOk; closeModal(); f && f(); };

/* ---------- API & aksi optimis ---------- */
// ── Transport: fetch ke GAS REST API (POST text/plain agar tanpa preflight CORS) ──
const GAS_URL = (window.CS_CONFIG && window.CS_CONFIG.GAS_URL) || '';
const GAS_SIAP = /^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(GAS_URL);
async function api(action, data) {
  if (!GAS_SIAP) return { success: false, message: 'Alamat server belum diatur. Isi GAS_URL di js/config.js dengan URL Web App (berakhiran /exec).' };
  let res;
  try {
    res = await fetch(GAS_URL, { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify({ action, token: S.token || '', data: data || {} }) });
  } catch (e) { throw new Error('Tidak dapat terhubung ke server.'); }
  let r;
  try { r = await res.json(); } catch (e) { throw new Error('Respons server tidak valid (HTTP ' + res.status + '). Periksa URL GAS_URL dan deployment Web App.'); }
  if (r && r.code === 'AUTH' && S.token) sesiBerakhir();
  return r;
}
async function aksi(action, data, o) {
  o = o || {}; const snap = o.opt ? o.opt() : null; if (o.opt) render();
  try {
    const r = await api(action, data);
    if (!r.success) { if (o.undo) { o.undo(snap); render(); } toast(r.message, 'danger'); return null; }
    if (o.ok) o.ok(r.data); if (o.msg !== false) toast(o.msg || r.message, 'success');
    if (o.refresh !== false) setTimeout(() => refreshData(true), 400);
    return r;
  } catch (e) { if (o.undo) { o.undo(snap); render(); } toast('Koneksi bermasalah: ' + (e && e.message || e), 'danger'); return null; }
}
function sesiBerakhir() { if (!S.token) return; toast('Sesi berakhir. Silakan masuk kembali.', 'warn'); doLogout(true); }
function setSync(st) { const el = $('#syn'); if (!el) return; el.className = 'syn' + (st === 'off' ? ' off' : ''); el.innerHTML = `<i></i>${st === 'busy' ? 'Menyinkronkan…' : st === 'off' ? 'Offline — data tersimpan' : 'Tersinkron ' + jam(S.lastSync || Date.now())}`; }
const editing = () => $('#modal-root').children.length || S.uploading || (document.activeElement && /^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName) && $('#view').contains(document.activeElement) && document.activeElement.dataset.input !== 'q');
async function refreshData(silent) {
  if (S.refreshing || !S.token) return; S.refreshing = true; setSync('busy');
  try {
    const r = await api('bootstrap');
    if (r.success) {
      // Bandingkan dengan data server terakhir: render ulang hanya bila memang berubah (hemat CPU & tidak mengganggu pengisian form)
      const sig = JSON.stringify(r.data), berubah = sig !== S.lastSig;
      S.data = r.data; S.me = r.data.me; S.lastSync = Date.now(); setSync('ok'); syncBrand(r.data.brand);
      if (berubah) {
        S.lastSig = sig; ls.set('cs_boot', sig); renderTop(); refreshBadges();
        if (editing()) S.dirty = true; else render();
      }
    }
    else if (r.code !== 'AUTH') { setSync('off'); if (!silent) toast(r.message, 'danger'); }
  } catch (e) { setSync('off'); if (!silent) toast('Tidak dapat terhubung ke server.', 'danger'); }
  finally { S.refreshing = false; }
}

/* ---------- Berkas, ekspor, cetak ---------- */
function loadScript(src) { return new Promise((res, rej) => { if (document.querySelector(`script[data-src="${src}"]`)) return res(); const s = document.createElement('script'); s.src = src; s.dataset.src = src; s.onload = res; s.onerror = () => rej(new Error('Gagal memuat ' + src)); document.head.appendChild(s); }); }
const safeCell = c => { c = String(c == null ? '' : c); return /^[=+\-@]/.test(c) ? "'" + c : c; };
function unduhBlob(nama, blob) { const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = nama; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500); }
function unduhCsv(nama, rows) { const csv = String.fromCharCode(0xFEFF) + rows.map(r => r.map(c => { c = safeCell(c); return /[",\n;]/.test(c) ? '"' + c.replace(/"/g, '""') + '"' : c; }).join(',')).join(String.fromCharCode(13, 10)); unduhBlob(nama + '.csv', new Blob([csv], { type: 'text/csv;charset=utf-8' })); }
async function unduhXlsx(nama, sheets) {
  try { await loadScript('https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js'); const wb = XLSX.utils.book_new(); sheets.forEach(s => XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(s.rows.map(r => r.map(safeCell))), s.nama.slice(0, 31))); const out = XLSX.write(wb, { bookType: 'xlsx', type: 'array' }); unduhBlob(nama + '.xlsx', new Blob([out], { type: 'application/octet-stream' })); toast('Berkas Excel diunduh.', 'success'); }
  catch (e) { unduhCsv(nama, sheets[0].rows); toast('Pustaka Excel tidak tersedia, diunduh sebagai CSV.', 'warn'); }
}
function cetak(judul, body) { $('#print-root').innerHTML = `<h1>${E(judul)}</h1><p>${E(bfull())} • dicetak ${E(tglJam(Date.now()))}</p>${body}`; setTimeout(() => { try { window.print(); } catch (e) { toast('Pencetakan diblokir browser. Unduh Excel sebagai alternatif.', 'warn'); } }, 60); }
const rowsToHtml = rows => '<table>' + rows.map((r, i) => '<tr>' + r.map(c => i ? '<td>' + E(c) + '</td>' : '<th>' + E(c) + '</th>').join('') + '</tr>').join('') + '</table>';
function bacaFile(file, onProg) { return new Promise((res, rej) => { if (file.size > 10 * 1048576) return rej(new Error('Ukuran berkas melebihi 10 MB.')); const fr = new FileReader(); fr.onprogress = e => onProg && e.lengthComputable && onProg(e.loaded / e.total); fr.onload = () => { const s = String(fr.result); res({ nama_file: file.name, mime: file.type || 'application/octet-stream', ukuran: file.size, b64: s.slice(s.indexOf(',') + 1) }); }; fr.onerror = () => rej(new Error('Gagal membaca berkas.')); fr.readAsDataURL(file); }); }
const dropzone = (id, hint) => `<div class="dz" data-dz="${id}" role="button" tabindex="0" data-act="dz.pick" data-id="${id}" aria-label="Pilih berkas">${icon('cloud-arrow-up-fill')}<div class="b mt" style="margin-top:8px">Tarik & lepas berkas di sini, atau <span style="color:var(--pri);text-decoration:underline">jelajahi berkas</span></div><div class="sm mut">${E(hint || 'Maksimal 10 MB')}</div><input type="file" id="fi_${id}" class="hidden" data-change="file" data-id="${id}"></div><div id="dzs_${id}" class="mt">${fileRow(id)}</div>`;
const fileRow = id => { const f = S.files[id]; return f ? `<div class="filebox"><div class="ic">${icon('file-earmark-zip')}</div><div class="f1"><div class="b ell">${E(f.name)}</div><div class="sm mut">${ukuran(f.size)} • siap diunggah</div><div class="bar sm mt" style="margin-top:6px" id="up_${id}"><i style="width:${f.prog || 0}%"></i></div></div><button class="ib sm" data-act="dz.clear" data-id="${id}" aria-label="Hapus berkas">${icon('trash')}</button></div>` : ''; };
function setFile(id, file) { if (file.size > 10 * 1048576) { toast('Ukuran berkas melebihi 10 MB.', 'danger'); return; } S.files[id] = file; const el = $('#dzs_' + id); if (el) el.innerHTML = fileRow(id); }
ACT['dz.pick'] = el => { const i = $('#fi_' + el.dataset.id); i && i.click(); };
ACT['dz.clear'] = el => { delete S.files[el.dataset.id]; const e = $('#dzs_' + el.dataset.id); if (e) e.innerHTML = ''; };
CHG.file = el => { if (el.files[0]) setFile(el.dataset.id, el.files[0]); el.value = ''; };
document.addEventListener('dragover', e => { const z = e.target.closest && e.target.closest('[data-dz]'); if (z) { e.preventDefault(); z.classList.add('over'); } });
document.addEventListener('dragleave', e => { const z = e.target.closest && e.target.closest('[data-dz]'); if (z) z.classList.remove('over'); });
document.addEventListener('drop', e => { const z = e.target.closest && e.target.closest('[data-dz]'); if (z) { e.preventDefault(); z.classList.remove('over'); if (e.dataTransfer.files[0]) setFile(z.dataset.dz, e.dataTransfer.files[0]); } });
async function pratinjau(jenis, id, nama) {
  modal({ title: 'Pratinjau: ' + nama, cls: 'wide', body: `<div class="tc" style="padding:40px"><span class="spin"></span><div class="mut mt">Mengambil berkas dari Google Drive…</div></div>` });
  try {
    const r = await api('berkas.ambil', { jenis, id }); if (!r.success) { $('#mdl-body').innerHTML = note(E(r.message), 'warn', 'exclamation-triangle'); return; }
    const bin = atob(r.data.b64), arr = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    const blob = new Blob([arr], { type: r.data.mime }), url = URL.createObjectURL(blob), inline = /pdf|image\//.test(r.data.mime);
    $('#mdl-body').innerHTML = (inline ? (/pdf/.test(r.data.mime) ? `<iframe src="${url}" style="width:100%;height:60vh;border:1px solid var(--bd);border-radius:8px" title="Pratinjau"></iframe>` : `<img src="${url}" alt="Pratinjau" style="max-width:100%;border-radius:8px">`) : note('Format ini tidak dapat dipratinjau di browser. Unduh berkas untuk membukanya.', '', 'file-earmark')) + `<div class="rowb mt"><span class="sm mut">${E(r.data.nama)} • ${ukuran(arr.length)}</span><button class="btn btn-p" data-act="blob.dl" data-url="${url}" data-nama="${E(r.data.nama)}">${icon('download')}Unduh</button></div>`;
  } catch (e) { $('#mdl-body').innerHTML = note('Gagal memuat berkas: ' + E(e.message || e), 'err', 'x-octagon'); }
}
ACT['blob.dl'] = el => { const a = document.createElement('a'); a.href = el.dataset.url; a.download = el.dataset.nama; document.body.appendChild(a); a.click(); a.remove(); };

/* ---------- Grafik (Chart.js) ---------- */
const css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();
const PAL = () => ({ pri: css('--pri') || '#1E4FD8', ok: '#10B981', warn: '#F59E0B', ind: '#6366F1', err: '#BA1A1A', mut: '#94A3B8', gr: css('--bd') || '#E2E8F0', tx: css('--tx3') || '#64748B' });
function destroyCharts() { Object.keys(S.charts).forEach(k => { try { S.charts[k].destroy(); } catch (e) { } }); S.charts = {}; }
function chart(id, cfg) {
  S.post.push(() => { const c = document.getElementById(id); if (!c) return; if (!window.Chart) { c.parentNode.innerHTML = '<div class="empty sm">Grafik tidak dapat dimuat (offline).</div>'; return; } const P = PAL(); Chart.defaults.font.family = "'Inter',system-ui,sans-serif"; Chart.defaults.color = P.tx; cfg.options = Object.assign({ responsive: true, maintainAspectRatio: false, animation: { duration: 350 } }, cfg.options || {}); S.charts[id] = new Chart(c, cfg); });
}
function lineChart(id, labels, sets, o) { o = o || {}; const P = PAL(); chart(id, { type: 'line', data: { labels, datasets: sets.map((s, i) => Object.assign({ borderColor: [P.pri, P.mut, P.ok][i] || P.pri, backgroundColor: i === 0 ? P.pri + '22' : 'transparent', fill: i === 0, tension: .35, pointRadius: 4, pointBackgroundColor: '#fff', pointBorderColor: [P.pri, P.mut, P.ok][i] || P.pri, pointBorderWidth: 2, borderWidth: 2.5, borderDash: s.dash ? [6, 5] : [] }, s)) }, options: { plugins: { legend: { display: sets.length > 1, position: 'bottom', labels: { boxWidth: 10, usePointStyle: true } } }, scales: { y: { min: o.min, max: o.max, grid: { color: P.gr }, border: { display: false } }, x: { grid: { display: false } } } } }); }
function barChart(id, labels, sets, o) { o = o || {}; const P = PAL(); chart(id, { type: 'bar', data: { labels, datasets: sets.map((s, i) => Object.assign({ backgroundColor: [P.pri, P.ok, P.ind, P.warn][i], borderRadius: 4, maxBarThickness: 36 }, s)) }, options: { indexAxis: o.h ? 'y' : 'x', plugins: { legend: { display: sets.length > 1, position: 'bottom', labels: { boxWidth: 10, usePointStyle: true } } }, scales: { y: { min: o.min, max: o.max, grid: { color: P.gr }, border: { display: false } }, x: { grid: { display: false } } } } }); }
function donutChart(id, labels, data, colors, center) { const P = PAL(); chart(id, { type: 'doughnut', data: { labels, datasets: [{ data, backgroundColor: colors || [P.pri, P.ok, P.ind, P.warn, P.err, P.mut], borderWidth: 2, borderColor: css('--card') || '#fff' }] }, options: { cutout: '70%', plugins: { legend: { display: false } } }, plugins: [{ id: 'ctr', afterDraw(ch) { if (!center) return; const { ctx, chartArea: a } = ch; ctx.save(); ctx.textAlign = 'center'; ctx.fillStyle = css('--tx') || '#0F172A'; ctx.font = '700 22px Inter'; ctx.fillText(center[0], (a.left + a.right) / 2, (a.top + a.bottom) / 2 + 2); ctx.font = '500 11px Inter'; ctx.fillStyle = P.tx; ctx.fillText(center[1] || '', (a.left + a.right) / 2, (a.top + a.bottom) / 2 + 18); ctx.restore(); } }] }); }
const legend = (labels, data, colors, suffix) => `<div class="legend">${labels.map((l, i) => `<div><i style="background:${colors[i]}"></i><span>${E(l)}</span><b>${data[i]}${suffix || ''}</b></div>`).join('')}</div>`;
