/* ---------- Komponen gaya dashboard ringkasan (kartu gradien, sparkline, ringkasan) ---------- */
const OVC = () => ['#2563eb', '#16a34a', '#7c3aed', '#f97316', '#06b6d4', '#ef4444', '#eab308'];
const kg = o => `<div class="kg kg-${o.c}"><div class="kg-ic">${icon(o.i)}</div><div class="f1" style="min-width:0"><div class="kg-l">${E(o.l)}</div><div class="kg-v">${o.v}</div>${o.s ? `<div class="kg-s">${o.s}</div>` : ''}</div></div>`;
const spark = vals => {
  vals = (vals || []).filter(v => v != null); if (vals.length < 2) return '<span class="mut">–</span>';
  const w = 96, h = 26, mn = Math.min.apply(null, vals), mx = Math.max.apply(null, vals), sp = (mx - mn) || 1, col = vals[vals.length - 1] < vals[0] ? '#ef4444' : '#16a34a';
  const pts = vals.map((v, i) => Math.round(i / (vals.length - 1) * (w - 6) + 3) + ',' + Math.round(h - 4 - (v - mn) / sp * (h - 8))).join(' ');
  return `<svg class="spark" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" aria-hidden="true"><polyline fill="none" stroke="${col}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="${pts}"/></svg>`;
};
function barColored(id, labels, data, colors) {
  chart(id, { type: 'bar', data: { labels, datasets: [{ data, backgroundColor: colors, borderRadius: 6, maxBarThickness: 42 }] }, options: { plugins: { legend: { display: false } }, scales: { y: { min: 0, max: 100, ticks: { callback: v => v + '%' }, grid: { color: PAL().gr }, border: { display: false } }, x: { grid: { display: false } } } },
    plugins: [{ id: 'vl', afterDatasetsDraw(ch) { const c = ch.ctx; c.save(); c.fillStyle = css('--tx') || '#0F172A'; c.font = '700 12px Inter'; c.textAlign = 'center'; ch.getDatasetMeta(0).data.forEach((b, i) => c.fillText(n0(data[i]) + '%', b.x, b.y - 6)); c.restore(); } }] });
}
const keepUp = () => `<div class="ovc keepup"><div><b>Terus semangat!</b><p>Usaha yang konsisten hari ini membawa hasil yang lebih baik di masa depan.</p><div class="stars">${icon('star-fill')}${icon('star-fill')}${icon('star-fill')}${icon('star-fill')}${icon('star-fill')}</div></div><div class="ku-ic">${icon('mortarboard-fill')}</div></div>`;
const ovNote = () => `<div class="ov-note">Data diperbarui: ${E(tglJam(S.lastSync || Date.now()))} &nbsp;|&nbsp; Sumber: Google Sheets ${E(bn())}</div>`;
const ovKodes = () => (D().matkul || []).filter(m => (!fval('ovta', '') || m.tahun_ajaran === fval('ovta', '')) && (!fval('ovsm', '') || m.semester === fval('ovsm', ''))).map(m => m.kode_mk);
function ovFilters() {
  const mk = D().matkul || [], ta = uniq(mk.map(m => m.tahun_ajaran)).filter(Boolean), sm = uniq(mk.map(m => m.semester)).filter(Boolean);
  return `<div class="ov-sel"><label>Tahun Akademik</label>${selx('ovta', [['', 'Semua']].concat(ta.map(x => [x, x])), '')}</div><div class="ov-sel"><label>Semester</label>${selx('ovsm', [['', 'Semua']].concat(sm.map(x => [x, x])), '')}</div>`;
}
function ovData(kodes) {
  const rows = []; kodes.forEach(k => ((D().rekap || {})[k] || []).forEach(r => rows.push(Object.assign({ k }, r))));
  const by = {}; rows.forEach(r => { by[r.email] = by[r.email] || { nama: r.nama, v: [] }; if (r.total != null) by[r.email].v.push(r.total); });
  const all = Object.keys(by), studs = all.map(e => ({ email: e, nama: by[e].nama, avg: avg(by[e].v) })).filter(s => s.avg != null);
  const band = (l, f, c) => ({ l, c, n: studs.filter(f).length });
  const bands = [band('Istimewa (85–100)', s => s.avg >= 85, '#7c3aed'), band('Baik (70–84)', s => s.avg >= 70 && s.avg < 85, '#16a34a'), band('Cukup (55–69)', s => s.avg >= 55 && s.avg < 70, '#2563eb'), band('Kurang (45–54)', s => s.avg >= 45 && s.avg < 55, '#f97316'), band('Gagal (<45)', s => s.avg < 45, '#ef4444')];
  const perMk = kodes.map(k => {
    const r = ((D().rekap || {})[k] || []), t = r.map(x => x.total).filter(v => v != null), ts = (D().tugas || []).filter(x => x.kode_mk === k && x.avgKelas != null).sort((a, b) => a.deadline - b.deadline).map(x => x.avgKelas);
    return { k, nama: mkNama(k), n: r.length, avg: avg(t), pass: t.length ? t.filter(v => v >= 55).length / t.length * 100 : null, dist: t.filter(v => v >= 85).length, fail: t.filter(v => v < 55).length, g: t.length, trend: ts };
  });
  return { total: all.length, studs, pass: studs.filter(s => s.avg >= 55).length, dist: studs.filter(s => s.avg >= 85).length, mean: avg(studs.map(s => s.avg)), bands, perMk, top: studs.slice().sort((a, b) => b.avg - a.avg).slice(0, 5) };
}
function overviewHtml(kodes, title, sub) {
  const d = ovData(kodes), C = OVC(), gN = d.studs.length, pc = (a, b) => b ? n1(a / b * 100) : '–', rk = ['r1', 'r2', 'r3'], pm = d.perMk.filter(m => m.pass != null);
  donutChart('c_ov1', d.bands.map(b => b.l), d.bands.map(b => b.n), d.bands.map(b => b.c), [gN, 'TOTAL']);
  barColored('c_ov2', d.perMk.map(m => m.k), d.perMk.map(m => m.avg || 0), d.perMk.map((m, i) => C[i % C.length]));
  donutChart('c_ov3', pm.map(m => m.k), pm.map(m => Math.round(m.pass)), pm.map((m, i) => C[i % C.length]), [pm.length ? n1(avg(pm.map(m => m.pass))) + '%' : '–', 'LULUS']);
  return `<div class="ov-h"><h1>${E(title)} <small>${E(sub)}</small></h1><div class="ov-f">${ovFilters()}<button class="ov-pr" data-act="ov.print" aria-label="Cetak ringkasan">${icon('printer')}</button></div></div>
  <div class="g5">${kg({ c: 'blue', i: 'people-fill', l: 'Total Mahasiswa', v: d.total, s: kodes.length + ' mata kuliah' })}${kg({ c: 'green', i: 'mortarboard-fill', l: 'Mahasiswa Lulus', v: d.pass, s: pc(d.pass, gN) + '% Tingkat Lulus' })}${kg({ c: 'purple', i: 'award-fill', l: 'Istimewa (≥85)', v: d.dist, s: pc(d.dist, gN) + '% dari Total' })}${kg({ c: 'orange', i: 'clipboard-data-fill', l: 'Rata-rata Nilai', v: n1(d.mean) + '%', s: 'Skala 0–100' })}${kg({ c: 'teal', i: 'percent', l: 'Tidak Lulus', v: pc(gN - d.pass, gN) + '%', s: (gN - d.pass) + ' mahasiswa' })}</div>
  <div class="ov3"><div class="ovc"><h3>Ringkasan Hasil</h3>${gN ? `<div class="cv sm"><canvas id="c_ov1"></canvas></div><div class="legend" style="margin-top:12px">${d.bands.map(b => `<div><i style="background:${b.c}"></i><span>${E(b.l)}</span><b>${b.n} (${pc(b.n, gN)}%)</b></div>`).join('')}</div>` : empty('pie-chart', 'Belum ada nilai.')}</div>
  <div class="ovc"><h3>Rata-rata Nilai per Mata Kuliah</h3>${d.perMk.length ? '<div class="cv"><canvas id="c_ov2"></canvas></div>' : empty('bar-chart', 'Belum ada mata kuliah.')}</div>
  <div class="ovc"><h3>${icon('trophy-fill')} Mahasiswa Berprestasi</h3>${d.top.length ? d.top.map((s, i) => `<div class="rank"><span class="n ${rk[i] || ''}">${i + 1}</span><span class="nm ell">${E(s.nama)}</span><span class="vv">${n1(s.avg)}%</span></div>`).join('') : empty('person', 'Belum ada nilai.')}</div></div>
  <div class="ov2"><div class="ovc"><h3>Ikhtisar Performa Mata Kuliah</h3>${tbl([{ h: 'Mata Kuliah', r: m => `<b>${E(m.k)}</b><div class="xs mut">${E(m.nama)}</div>` }, { h: 'Total Mhs', r: m => m.n }, { h: 'Rata-rata', r: m => m.avg == null ? '–' : n1(m.avg) + '%' }, { h: 'Tingkat Lulus', r: m => m.pass == null ? '–' : n1(m.pass) + '%' }, { h: 'Istimewa', r: m => m.g ? m.dist + ' (' + pc(m.dist, m.g) + '%)' : '–' }, { h: 'Tidak Lulus', r: m => m.g ? m.fail + ' (' + pc(m.fail, m.g) + '%)' : '–' }, { h: 'Tren', r: m => spark(m.trend) }], d.perMk, { cls: 'navy', em: 'Belum ada data.' })}</div>
  <div class="col"><div class="ovc"><h3>Tingkat Lulus per Mata Kuliah</h3>${pm.length ? `<div class="cv sm"><canvas id="c_ov3"></canvas></div><div class="legend" style="margin-top:12px">${pm.map((m, i) => `<div><i style="background:${C[i % C.length]}"></i><span>${E(m.k)}</span><b>${n1(m.pass)}%</b></div>`).join('')}</div>` : empty('pie-chart', 'Belum ada data.')}</div>${keepUp()}</div></div>`;
}
ACT['ov.print'] = () => { const d = ovData(ovKodes()); cetak('Ringkasan Performa Akademik', rowsToHtml([['Kode', 'Mata Kuliah', 'Total Mhs', 'Rata-rata', 'Tingkat Lulus %', 'Istimewa', 'Tidak Lulus']].concat(d.perMk.map(m => [m.k, m.nama, m.n, m.avg == null ? '' : n1(m.avg), m.pass == null ? '' : n1(m.pass), m.dist, m.fail])))); };

