function doSearch(q) {
  q = lc(q.trim()); if (q.length < 2) return []; const d = D(), r = S.me.role, out = [];
  (d.materi || []).forEach(m => { if (lc(m.judul + ' ' + m.deskripsi + ' ' + mkNama(m.kode_mk)).includes(q)) out.push({ ic: 'book', t: m.judul, s: 'Materi • ' + m.kode_mk, v: r === 'mahasiswa' ? 'm.materi' : 'd.materi', k: m.kode_mk }); });
  (d.tugas || []).forEach(t => { if (lc(t.judul + ' ' + t.deskripsi + ' ' + mkNama(t.kode_mk)).includes(q)) out.push({ ic: 'journal-text', t: t.judul, s: 'Tugas • ' + t.kode_mk, v: r === 'mahasiswa' ? 'm.tugasDetail' : 'd.tugas', id: t.id, k: t.kode_mk }); });
  (d.pengumuman || []).forEach(a => { if (lc(a.judul + ' ' + a.isi).includes(q)) out.push({ ic: 'megaphone', t: a.judul, s: 'Pengumuman • ' + a.kategori, v: 'pengumuman', id: a.id }); });
  if (r === 'dosen') (d.mhs || []).forEach(m => { if (lc(m.nama + ' ' + m.nim).includes(q)) out.push({ ic: 'person', t: m.nama, s: 'Mahasiswa • ' + m.nim, v: 'd.rekap', q: m.nama }); });
  if (r === 'admin') { (d.users || []).forEach(u => { if (lc(u.nama + ' ' + u.nim_nip + ' ' + u.email).includes(q)) out.push({ ic: 'person', t: u.nama, s: u.role + ' • ' + u.nim_nip, v: 'a.pengguna', q: u.nama }); }); (d.matkul || []).forEach(m => { if (lc(m.kode_mk + ' ' + m.nama_mk).includes(q)) out.push({ ic: 'mortarboard', t: m.nama_mk, s: 'Mata kuliah • ' + m.kode_mk, v: 'a.matkul', q: m.kode_mk }); }); }
  return out.slice(0, 8);
}
