  const d = D(), m = S.me, now = Date.now(), nd = nextDue(), rs = d.ringkas || {}, all = myTugas(), done = all.filter(t => pengOf(t.id)).length, gr = gradedPeng(), rata = avg(gr.map(x => x.p.nilai)), ht = hadirTot(), rek = rekapAll(), C = OVC(), mk0 = (d.matkul || [])[0] || {};
  donutChart('c_ov1', rek.map(x => x.k), rek.map(x => x.r.total || 0), rek.map((x, i) => C[i % C.length]), [n1(rata), 'RATA-RATA']);
