  const hp = rek.filter(x => x.r.pct != null); donutChart('c_ov3', hp.map(x => x.k), hp.map(x => Math.round(x.r.pct)), hp.map((x, i) => C[i % C.length]), [ht.pct == null ? '–' : n0(ht.pct) + '%', 'HADIR']);
  const agenda = [].concat((d.sesi || []).filter(s => s.status !== 'Selesai').map(s => ({ ts: s.mulai, t: 'Kuliah: ' + mkNama(s.kode_mk), s: s.topik + ' • ' + (s.ruang || ''), tag: s.status === 'Aktif' ? chip('LIVE', 'ok', 'pulse') : chip('Terjadwal', 'info') })), myTugas().filter(t => !pengOf(t.id) && t.deadline > now && t.status === 'Terbit').map(t => ({ ts: t.deadline, t: t.judul, s: 'Tenggat ' + tglJam(t.deadline), tag: chip(sisaTeks(t.deadline), t.deadline - now < 864e5 ? 'err' : 'warn') }))).sort((a, b) => a.ts - b.ts).slice(0, 5);
  const rows = (d.matkul || []).map(mk => { const ts = myTugas().filter(t => t.kode_mk === mk.kode_mk); return { mk, r: rekapMe(mk.kode_mk), tot: ts.length, sub: ts.filter(t => pengOf(t.id)).length, series: gr.filter(x => x.t.kode_mk === mk.kode_mk).map(x => x.p.nilai) }; });
