  <div class="card mt" style="background:linear-gradient(120deg,var(--pri),var(--pri-d));border:0"><div class="row wrap"><div class="f1" style="min-width:220px;color:#333">${qinp('materi', 'Cari judul materi, topik, atau nama dosen…')}</div>${selx('mm', [['', 'Semua Mata Kuliah (' + mk.length + ')']].concat(mk.map(m => [m.kode_mk, m.kode_mk + ' • ' + m.nama_mk])), '')}${selx('mf', [['', 'Semua Format'], ['pdf', 'PDF'], ['pptx', 'Slide (PPTX)'], ['zip', 'ZIP / Kode'], ['docx', 'Dokumen'], ['link', 'Tautan']], '')}${selx('ms', [['new', 'Terbaru'], ['az', 'Judul A–Z']], 'new')}</div><div class="sm" style="color:#DCE4FF;margin-top:10px;text-align:right">Menampilkan ${ls_.length} materi relevan</div></div>
