const avatarInner = m => (m && m.foto ? `<img src="${E(m.foto)}" alt="Foto profil" style="width:100%;height:100%;object-fit:cover;border-radius:inherit">` : E(inisial(m && m.nama)));
function kecilkanFoto(file) {
  return new Promise((res, rej) => {
    const fr = new FileReader();
    fr.onerror = () => rej(new Error('Gagal membaca berkas.'));
    fr.onload = () => {
      const im = new Image();
      im.onerror = () => rej(new Error('Berkas bukan gambar yang valid.'));
      im.onload = () => {
        const c = document.createElement('canvas'), m = Math.min(im.width, im.height), sx = (im.width - m) / 2, sy = (im.height - m) / 2;
        c.width = c.height = 160; c.getContext('2d').drawImage(im, sx, sy, m, m, 0, 0, 160, 160);
        for (const q of [0.82, 0.7, 0.55]) { const u = c.toDataURL('image/jpeg', q); if (u.length <= 60000) return res(u); }
        rej(new Error('Foto terlalu rumit. Gunakan foto yang lebih sederhana.'));
      };
      im.src = String(fr.result);
    };
    fr.readAsDataURL(file);
  });
}
function setFotoLokal(data) { S.me.foto = data; if (S.data && S.data.me) S.data.me.foto = data; renderTop(); }
ACT['foto.pick'] = () => { const i = $('#foto_file'); i && i.click(); };
CHG.foto = async el => {
  const f = el.files[0]; el.value = ''; if (!f) return;
  if (f.type.indexOf('image/') !== 0) { toast('Pilih berkas gambar.', 'warn'); return; }
  try {
    const data = await kecilkanFoto(f), r = await api('profil.foto', { foto: data });
    if (r.success) { setFotoLokal(data); toast(r.message, 'success'); render(); } else toast(r.message, 'danger');
  } catch (e) { toast(e.message || 'Gagal memproses foto.', 'danger'); }
};
ACT['foto.del'] = () => confirmBox('Hapus foto profil Anda?', async () => {
  const r = await api('profil.foto', { foto: '' });
  if (r.success) { setFotoLokal(''); toast(r.message, 'success'); render(); } else toast(r.message, 'danger');
}, 'Hapus', true);

