ACT['mat.open'] = el => { api('materi.unduh', { id: el.dataset.id }).catch(() => { }); };
ACT['mat.dl'] = async el => { const m = (D().materi || []).find(x => x.id === el.dataset.id); if (!m) return; toast('Menyiapkan unduhan…', 'info'); try { const r = await api('berkas.ambil', { jenis: 'materi', id: m.id }); if (!r.success) { toast(r.message, 'danger'); return; } const bin = atob(r.data.b64), a = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i); unduhBlob(r.data.nama, new Blob([a], { type: r.data.mime })); api('materi.unduh', { id: m.id }).catch(() => { }); } catch (e) { toast('Gagal mengunduh.', 'danger'); } };

