function loadImg(file, max) {
  return new Promise((res, rej) => {
    if (file.size > max * 1048576) return rej(new Error('Gambar terlalu besar (maks. ' + max + ' MB).'));
    const fr = new FileReader(); fr.onerror = () => rej(new Error('Gagal membaca gambar.'));
    fr.onload = () => { const im = new Image(); im.onerror = () => rej(new Error('Berkas bukan gambar yang valid.')); im.onload = () => res(im); im.src = String(fr.result); };
    fr.readAsDataURL(file);
  });
}
async function shrinkLogo(file) {
  const im = await loadImg(file, 6), W = im.naturalWidth || im.width || 256, H = im.naturalHeight || im.height || 256;
  for (const sz of [256, 192, 128, 96]) for (const f of ['image/png', 'image/webp', 'image/jpeg']) {
    const sc = Math.min(1, sz / Math.max(W, H)), w = Math.max(1, Math.round(W * sc)), h = Math.max(1, Math.round(H * sc)), c = document.createElement('canvas'); c.width = w; c.height = h; const x = c.getContext('2d');
    if (f === 'image/jpeg') { x.fillStyle = '#fff'; x.fillRect(0, 0, w, h); } x.drawImage(im, 0, 0, w, h); const u = c.toDataURL(f, 0.85);
    if (u.indexOf('data:' + f) === 0 && u.length <= 40000) return u;
  }
  throw new Error('Logo terlalu rumit untuk disimpan. Gunakan logo yang lebih sederhana.');
}
async function shrinkBg(file) {
  const im = await loadImg(file, 12), W = im.naturalWidth || im.width || 1280, H = im.naturalHeight || im.height || 720;
  for (const sz of [1280, 1024, 800, 640]) for (const q of [0.8, 0.7, 0.6, 0.5, 0.4]) {
    const sc = Math.min(1, sz / Math.max(W, H)), w = Math.max(1, Math.round(W * sc)), h = Math.max(1, Math.round(H * sc)), c = document.createElement('canvas'); c.width = w; c.height = h; const x = c.getContext('2d');
    x.fillStyle = '#fff'; x.fillRect(0, 0, w, h); x.drawImage(im, 0, 0, w, h); const u = c.toDataURL('image/jpeg', q);
    if (u.length <= 200000) return u;
  }
  throw new Error('Gambar terlalu rumit untuk disimpan. Gunakan gambar yang lebih sederhana.');
}
CHG.logofile = async el => { const f = el.files[0]; el.value = ''; if (!f) return; if (f.type.indexOf('image/') !== 0) { toast('Pilih berkas gambar.', 'warn'); return; } try { const u = await shrinkLogo(f); S.brandDraft.logo = u; S.brandDraft.cLogo = true; updBrandPrev(); toast('Logo siap disimpan (' + Math.round(u.length / 1024) + ' KB). Klik Simpan Perubahan.', 'success'); } catch (e) { toast(e.message || 'Gagal memproses gambar.', 'danger'); } };
CHG.bgfile = async el => { const f = el.files[0]; el.value = ''; if (!f) return; if (f.type.indexOf('image/') !== 0) { toast('Pilih berkas gambar.', 'warn'); return; } try { const u = await shrinkBg(f); S.brandDraft.bg = u; S.brandDraft.cBg = true; updBrandPrev(); toast('Gambar latar siap disimpan (' + Math.round(u.length / 1024) + ' KB). Klik Simpan Perubahan.', 'success'); } catch (e) { toast(e.message || 'Gagal memproses gambar.', 'danger'); } };
ACT['brand.pick'] = () => { const i = $('#bd_file'); i && i.click(); };
ACT['brand.pickbg'] = () => { const i = $('#bd_bgfile'); i && i.click(); };
ACT['brand.nologo'] = () => { if (S.brandDraft) { S.brandDraft.logo = ''; S.brandDraft.cLogo = true; updBrandPrev(); } };
ACT['brand.nobg'] = () => { if (S.brandDraft) { S.brandDraft.bg = ''; S.brandDraft.cBg = true; updBrandPrev(); } };
ACT['brand.reset'] = () => { const L = BR0.login; S.brandDraft = { nama: BR0.nama, subjudul: BR0.subjudul, logo: '', logoSize: 56, bg: '', judul1: L.judul1, judul2: L.judul2, sub: L.sub, poin: L.poin, cLogo: true, cBg: true }; render(); toast('Nilai bawaan dimuat. Klik Simpan Perubahan untuk menerapkan.', 'info'); };
ACT['brand.save'] = async el => {
  const d = S.brandDraft; if (!d || !String(d.nama).trim()) { toast('Nama aplikasi wajib diisi.', 'warn'); return; }
  const data = { nama: d.nama, subjudul: d.subjudul, logoSize: d.logoSize, login: { judul1: d.judul1, judul2: d.judul2, sub: d.sub, poin: d.poin } }; if (d.cLogo) data.logo = d.logo; if (d.cBg) data.bg = d.bg;
  el.disabled = true; const r = await aksi('brand.simpan', data, { refresh: false }); el.disabled = false; if (r) { applyBrand(r.data); S.brandDraft = null; render(); }
};

